def fix_words(words):
    i = 0
    while i < len(words) - 1:
        num_quotes = 0
        for char in reversed(words[i]):
            if char == \"'\":
                num_quotes += 1
            else:
                break
        if num_quotes % 2 != 0:
            words[i+1] = \"'\" + words[i+1]
            words[i] = words[i][:-1]
            if not words[i]:
                words.pop(i)
                continue
        i += 1
    return words

from astropy.io.fits.util import _words_group

for n in range(60, 70):
    val = 'x' * n + \"''\"
    escaped = val.replace(\"'\", \"''\")
    words = _words_group(escaped, 67)
    words = fix_words(list(words))
    print(n, words)
"

