from functools import partialmethod

class Model:
    def _get_FIELD_display(self, field):
        return 'default'

class Field:
    def __init__(self, name):
        self.name = name

    def contribute_to_class(self, cls):
        attr_name = 'get_%s_display' % self.name

        # Check MRO for an existing attribute
        has_custom = False
        for klass in cls.__mro__:
            if attr_name in klass.__dict__:
                value = klass.__dict__[attr_name]
                if not (isinstance(value, partialmethod) and value.func == cls._get_FIELD_display):
                    has_custom = True
                break

        if not has_custom:
            setattr(cls, attr_name, partialmethod(cls._get_FIELD_display, field=self))

# Case 1: No override
class FooBar1(Model):
    pass

f1 = Field('foo')
f1.contribute_to_class(FooBar1)
print("FooBar1 override:", FooBar1().get_foo_display()) # Should be default

# Case 2: Same class override
class FooBar2(Model):
    def get_foo_display(self):
        return 'custom'

f2 = Field('foo')
f2.contribute_to_class(FooBar2)
