import html

def get_original_suffix(middle, stripped_suffix):
    if not stripped_suffix:
        return ''
    for i in range(1, len(middle) + 1):
        suffix = middle[-i:]
        if html.unescape(suffix) == stripped_suffix:
            return suffix
    return stripped_suffix # Fallback

