import unittest
from django.db import migrations, models
from django.db.migrations.optimizer import MigrationOptimizer

class IndexOptimizerTests(unittest.TestCase):
    def setUp(self):
        self.optimizer = MigrationOptimizer()

    def assertOptimizesTo(self, operations, expected):
        result = self.optimizer.optimize(operations, "migrations")
        # We compare their deconstructed states to make comparison easier
        self.assertEqual(
            [op.deconstruct() for op in result],
            [op.deconstruct() for op in expected]
        )

    def test_add_remove_index_cancels_out(self):
        """
        Adding an index and then removing it on the same model should cancel out completely.
        """
        self.assertOptimizesTo(
            [
                migrations.AddIndex("Pony", models.Index(fields=["name"], name="pony_name_idx")),
                migrations.RemoveIndex("Pony", "pony_name_idx"),
            ],
            []
        )

    def test_add_rename_index_old_name(self):
        """
        AddIndex and RenameIndex with old_name on the same index should reduce to a single AddIndex with the new name.
        """
        self.assertOptimizesTo(
            [
                migrations.AddIndex("Pony", models.Index(fields=["name"], name="pony_name_idx")),
                migrations.RenameIndex("Pony", new_name="pony_new_idx", old_name="pony_name_idx"),
            ],
            [
                migrations.AddIndex("Pony", models.Index(fields=["name"], name="pony_new_idx")),
            ]
        )

