import sys
import unicodedata

# Build the dict of combining characters
combining_dict = {}
for i in range(sys.maxunicode + 1):
    if 0xd800 <= i <= 0xdfff:
        continue
    if unicodedata.combining(chr(i)):
        combining_dict[i] = None

def original(s):
    normalized = unicodedata.normalize('NFKD', s)
    if normalized == s:
        return s
    else:
        return ''.join([c for c in normalized if not unicodedata.combining(c)])

def with_translate(s):
    return unicodedata.normalize('NFKD', s).translate(combining_dict)

# Test cases
test_cases = [
    'àáâãäåçèéêë',
    'ìíîïñòóôõöùúûüý',
    '\u0625',  # Arabic alef with hamza
    'this is à test',
    chr(241),
    chr(110) + chr(771),
    # A mix of complex unicode characters, emojis, etc.
    "😀 😃 😄 😁 😆 😅 😂 🤣",
    "Let's test combining characters: a\u0301 e\u0301 i\u0301 o\u0301 u\u0301",
    "Multiple combining: a\u0300\u0301\u0302",
]

for s in test_cases:
    orig_res = original(s)
    new_res = with_translate(s)
    # Note that original(chr(110) + chr(771)) is bugged, so we don't assert they are equal there.
    # Instead, we check if new_res is equal to the CORRECT/expected output 'n'.
    if s == chr(110) + chr(771):
        assert new_res == 'n', f"Expected 'n' for {repr(s)}, got {repr(new_res)}"
        print(f"Success for bugged case: {repr(s)} -> {repr(new_res)}")
    else:
        assert orig_res == new_res, f"Mismatch for {repr(s)}: original={repr(orig_res)}, new={repr(new_res)}"
        print(f"Success for: {repr(s)} -> {repr(new_res)}")

print("All tests passed!")
